from difflib import SequenceMatcher, get_close_matches

def norm(name):
    import re
    name = name.lower()
    name = re.sub(r'[^\w\s]', '', name)
    name = ' '.join(name.split())
    repl = {"limited":"ltd","incorporated":"inc","corporation":"corp","company":"co"}
    words = [repl.get(w,w) for w in name.split()]
    # remove common suffix tokens
    suffixes = {"inc","ltd","llc","corp","co"}
    words = [w for w in words if w not in suffixes]
    return ' '.join(words)

names = ['boundary corp','fraudulent corp','vendor 11','fuzzy match systems inc.','fuzzy match systems']
for a in names:
    for b in names:
        if a==b: continue
        s = SequenceMatcher(None, norm(a), norm(b)).ratio()
        if a=='fraudulent corp' or b=='fraudulent corp':
            print(a, b, s, norm(a), norm(b))

choices = [norm('Boundary Corp'), norm('Vendor 11'), norm('Fuzzy Match Systems')]
print('choices', choices)
print('match', get_close_matches(norm('Fraudulent Corp'), choices, n=1, cutoff=0.82))
print('match2', get_close_matches(norm('Fuzzy Match Systems Inc.'), choices, n=1, cutoff=0.82))
